verus! {
    //-------------------------------------------------------------------------
    // 1) Pure (ghost) specification of factorial on the naturals.
    //
    #[verifier::spec]
    fn factorial(n: nat) -> nat
        decreases n
    {
        if n == 0 {
            1
        } else {
            n * factorial(n - 1)
        }
    }

    //-------------------------------------------------------------------------
    // 2) Implementation of factorial_of_last_digit.
    //
    //    We compute ld = n % 10, then loop i = 1..=ld maintaining
    //      f == factorial(i-1)
    //    so that at the end f == factorial(ld).
    //
    fn factorial_of_last_digit(n: u64) -> (fact: u64)
        ensures (fact as nat) == factorial((n % 10) as nat)
        ensures fact <= 362_880
    {
        let ld: u64 = n % 10;
        let mut i: u64 = 1;
        let mut f: u64 = 1;
        // Loop from i = 1 up to ld, accumulating f = 1*2*...*i
        while i <= ld
            invariant 1 <= i && i <= ld + 1
            invariant (f as nat) == factorial((i - 1) as nat)
            decreases ld - (i - 1)
        {
            f = f * i;
            i = i + 1;
        }
        // Now i == ld+1 and f == factorial(ld)
        assert((f as nat) == factorial(ld as nat));
        // return the computed factorial
        fact = f;
    }
}